catch / unreachable:
fn risky(should_fail: bool) !i32 {
    if (should_fail) return error.Fail;
    return 42;
}

const a = risky(false) catch |e| {
    std.debug.print("caught: {}\n", .{e});
    return;
};

const b = risky(false) catch 0;  // default on error

const c = risky(false) catch unreachable;  // assert no error
const d = risky(false) catch return;  // propagate

std.debug.print("{d} {d}\n", .{a, b});

try Keyword:
fn mayFail(ok: bool) !i32 {
    if (!ok) return error.Fail;
    return 100;
}

fn caller() !void {
    const val = try mayFail(true);   // unwraps to 100
    const val2 = try mayFail(false); // returns error.Fail from caller
    std.debug.print("{d}\n", .{val + val2});
}

pub fn main() void {
    caller() catch |e| {
        std.debug.print("error: {}\n", .{e});
    };
}

