Shadowing & Blocks:
const std = @import("std");

pub fn main() void {
    const x: u32 = 10;
    {
        // Inner scope shadows outer x
        const x: u32 = 20;
        std.debug.print("inner x = {d}\n", .{x});
    }
    std.debug.print("outer x = {d}\n", .{x});

    // Block returns value
    const result = blk: {
        const a = 5;
        const b = 7;
        break :blk a + b;
    };
    std.debug.print("block result = {d}\n", .{result});

    // Labeled while
    var i: u32 = 0;
    outer: while (i < 5) {
        var j: u32 = 0;
        while (j < 5) {
            if (j > 2) break :outer;
            j += 1;
        }
        i += 1;
    }
    std.debug.print("i = {d}\n", .{i});
}

