const std = @import("std");

pub fn main() void {
    const maybe: ?u32 = 42;

    // orelse with default
    const val = maybe orelse 0;
    std.debug.print("val = {d}\n", .{val});

    // Capture syntax
    if (maybe) |n| {
        std.debug.print("Got {d}\n", .{n});
    } else {
        std.debug.print("Got null\n", .{});
    }

    // Assert non-null
    const asserted = maybe.?;
    _ = asserted;

    // While optional
    var iter = ([]const u8{ "a", "b", "c" }).[0..];
    while (iter.len > 0) {
        const ch = iter[0];
        iter = iter[1..];
        std.debug.print("{c} ", .{ch});
    }
    std.debug.print("\n", .{});

    // Chaining
    const result = foo() orelse bar() orelse 0;
    _ = result;
}

