const std = @import("std");

// Custom stack allocator
const StackAllocator = struct {
    buffer: []u8,
    index: usize = 0,

    fn allocator(self: *StackAllocator) std.mem.Allocator {
        return .{
            .ptr = self,
            .vtable = &.{
                .alloc = allocFn,
                .resize = resizeFn,
                .free = freeFn,
            },
        };
    }

    fn allocFn(ctx: *anyopaque, len: usize, alignment: u29, ret_addr: usize) ?[]u8 {
        const self: *StackAllocator = @ptrCast(@alignCast(ctx));
        const start = self.index;
        const end = start + len;
        if (end > self.buffer.len) return null;
        self.index = end;
        return self.buffer[start..end];
    }

    fn freeFn(ctx: *anyopaque, buf: []u8) void {
        _ = ctx;
        _ = buf;
        // Stack allocator does not support individual frees
    }

    fn resizeFn(ctx: *anyopaque, buf: []u8, new_len: usize, alignment: u29, ret_addr: usize) bool {
        _ = ctx;
        _ = buf;
        _ = new_len;
        _ = alignment;
        _ = ret_addr;
        return false; // Stack allocator does not resize
    }
};

