    const content = try std.fs.cwd().readFileAlloc(allocator, "input.txt", 1024 * 1024);
    defer allocator.free(content);

    // Write to file
    const file = try std.fs.cwd().createFile("output.txt", .{});
    defer file.close();
    try file.writeAll("Hello from Zig!");

    // List directory
    var dir = try std.fs.cwd().openDir("data", .{ .iterate = true });
    defer dir.close();

    var walker = try dir.walk(allocator);
    defer walker.deinit();

    while (try walker.next()) |entry| {
        std.debug.print("{}: {s}\n", .{ entry.kind, entry.path });
    }

    // Environment variables
    if (std.process.getEnvVarOwned(allocator, "HOME")) |home| {
        defer allocator.free(home);
        std.debug.print("Home dir: {s}\n", .{home});
    } else |err| {
        std.debug.print("HOME not set: {}\n", .{err});
    }
}

