const std = @import("std");

// Simple TCP echo server
pub fn main() !void {
    const address = try std.net.Address.parseIp("127.0.0.1", 8080);

    var server = try address.listen(.{
        .reuse_port = true,
    });
    defer server.deinit();

    std.debug.print("Server listening on {}...\n", .{address});

    // Accept connections in a loop
    while (true) {
        const connection = try server.accept();

        // Handle connection (in a real app, spawn a thread or event loop)
        const handler = struct {
            fn handle(conn: std.net.Server.Connection) void {
                var buf: [1024]u8 = undefined;
                if (conn.stream.read(&buf)) |n| {
                    _ = conn.stream.write(buf[0..n]) catch {};
                } else |_| {}
                conn.stream.close();
            }
        }.handle;

        handler(connection);
    }
}

// HTTP client request
fn fetchUrl(allocator: std.mem.Allocator, url: []const u8) ![]u8 {
    const uri = try std.Uri.parse(url);
    const host = uri.host.?;
    const port: u16 = uri.port orelse 80;

    const stream = try std.net.tcpConnectToHost(allocator, host, port);
    defer stream.close();

    // Send HTTP GET request
    try stream.writeAll("GET / HTTP/1.1\r\n");
    try stream.writeAll("Host: " ++ host ++ "\r\n");
    try stream.writeAll("Connection: close\r\n");
    try stream.writeAll("\r\n");

    // Read response
    var response = std.ArrayList(u8).init(allocator);
    defer response.deinit();

    var buf: [4096]u8 = undefined;
    while (true) {
        const n = try stream.read(&buf);
        if (n == 0) break;
        try response.appendSlice(buf[0..n]);
    }

    return response.toOwnedSlice();
}
